const { existsSync } = await import('node:fs');
const hwpPath = process.env.HWP_PATH;
if (!hwpPath) throw new Error('Missing HWP_PATH');
if (!existsSync(hwpPath)) throw new Error('HWP file not found at ' + hwpPath);
globalThis.hwpPath = hwpPath;
globalThis.outputPath = '/tmp/output.pdf';

const { readFileSync, writeFileSync } = await import('node:fs');
const mod = await import('@ohah/hwpjs');
const toPdf = (mod.toPdf) || (mod.default && mod.default.toPdf) || (mod.default?.toPdf);
if (!toPdf) throw new Error('toPdf function not found in @ohah/hwpjs');
const data = readFileSync(globalThis.hwpPath);
const pdfBuffer = toPdf(data, { font_dir: './fonts', embed_images: true });
writeFileSync(globalThis.outputPath, pdfBuffer);
